  'annual_general_meeting_for_q2_2026_financial_review_agenda_budget_approval_security_upgrade_proposal_amenity_booking_policy_update': 'Q2 2026 ఆర్థిక సమీక్ష కోసం వార్షిక సాధారణ సమావేశం. ఎజెండా: బడ్జెట్ ఆమోదం, భద్రతా అప్‌గ్రేడ్ ప్రతిపాదన, సదుపాయాల బుకింగ్ విధానం అప్‌డేట్.',
