  'government_mandated_elevator_inspection_for_block_c_lifts_expected_completion_4_hours_stairways_accessible_at_all_times': 'బ్లాక్ C లిఫ్ట్‌ల కోసం ప్రభుత్వం తప్పనిసరి చేసిన లిఫ్ట్ తనిఖీ. అంచనా వేసిన సమయం: 4 గంటలు. మెట్లు ఎల్లప్పుడూ అందుబాటులో ఉంటాయి.',
  'new_visitor_parking_policy': 'కొత్త సందర్శకుల పార్కింగ్ విధానం',
  'effective_1_august_2026_visitor_parking_is_limited_to_2_hours_per_visit_between_9_am_and_9_pm_residents_must_pre_register_visitors_via_the_portal': '1 ఆగస్టు 2026 నుండి, ఉదయం 9 నుండి రాత్రి 9 గంటల మధ్య సందర్శకుల పార్కింగ్ ఒక సందర్శనకు 2 గంటలకు పరిమితం చేయబడింది. నివాసితులు పోర్టల్ ద్వారా సందర్శకులను ముందుగా నమోదు చేసుకోవాలి.',
